import {reflectionEnvironment} from './studio-materials.js';
import {studioEnvironment,fittedDistance} from './discipline-render.js';
import * as THREE from './vendor/three.module.js';
import { OrbitControls } from './vendor/OrbitControls.js';
import { modelSTL } from './discipline-models.js';
export function createDisciplineViewer(host,{onEdit,onExport}={}){
  host.innerHTML=`<aside class="discipline-sidebar"><div class="discipline-intro"><span class="eyebrow">ESTUDIO DE GEOMETRÍA</span><h1 id="disciplineTitle">Modelo de ingeniería</h1><p id="disciplineDesignStatus" class="discipline-design-status"></p><details class="discipline-assumptions"><summary>Geometría y supuestos</summary><p id="disciplineAssumptions"></p></details></div><div id="disciplineSettingsHost"></div></aside><section class="discipline-workspace"><div class="discipline-toolbar"><div role="group" aria-label="Cámara del estudio"><button data-view="iso">◇ Perspectiva</button><button data-view="front">▣ Frente</button><button data-view="back">↻ Trasera</button><button data-view="side">◐ Lateral</button><button data-view="top">▤ Superior</button><button data-view="fit">⌗ Encuadrar</button></div><div><button id="disciplineCapture">↗ Captura</button><button id="disciplineJSON">↓ Datos JSON</button><button id="disciplineSTL">↓ Modelo STL</button></div></div><div class="discipline-stage"><div id="disciplineCanvas"></div><div class="discipline-view-tools"><button id="disciplineMeasure" aria-pressed="false">↔ Medir superficies</button><label><input id="disciplineWire" type="checkbox"> Aristas</label><label><input id="disciplineCut" type="checkbox"> Sección visual</label><label><input id="disciplineGrid" type="checkbox" checked> Cuadrícula</label></div><output id="disciplineDistance" class="discipline-distance">Órbita libre · rueda para acercar</output><div id="disciplineBadge" class="discipline-badge"></div></div><div id="disciplineSummary" class="discipline-summary"></div></section>`;
  const $=id=>host.querySelector('#'+id);let environment,skyEnvironment,skyImage;let renderer,scene,camera,controls,current,grid,ground,visible=false,needsRender=true,measure=false,measurePoints=[],markers=[],line,lastView='iso',visualKey=null;
  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
  function init(){if(renderer)return;renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.92;renderer.localClippingEnabled=true;renderer.domElement.setAttribute('aria-label','Modelo especializado: arrastra para orbitar, usa la rueda para acercar.');$('disciplineCanvas').append(renderer.domElement);scene=new THREE.Scene();scene.background=new THREE.Color('#edf2f7');environment=studioEnvironment(renderer);scene.environment=environment.texture;camera=new THREE.PerspectiveCamera(38,1,.001,1000);controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.addEventListener('change',()=>{needsRender=true;});controls.maxPolarAngle=Math.PI*.98;scene.add(new THREE.HemisphereLight(0xffffff,0x8c98aa,.7));const key=new THREE.DirectionalLight(0xfff5df,1.8);key.position.set(-5,8,7);key.castShadow=true;key.shadow.mapSize.set(2048,2048);scene.add(key);const fill=new THREE.DirectionalLight(0xb5d4ff,.5);fill.position.set(5,3,-4);scene.add(fill);new ResizeObserver(resize).observe($('disciplineCanvas'));renderer.domElement.addEventListener('pointerdown',pick);}
  function resize(){if(!renderer||!visible)return;const w=$('disciplineCanvas').clientWidth,h=$('disciplineCanvas').clientHeight;if(!w||!h)return;renderer.setSize(w,h);needsRender=true;camera.aspect=w/h;camera.updateProjectionMatrix();}
  function clearMeasure(){needsRender=true;for(const o of [...markers,...(line?[line]:[])]){o.removeFromParent();o.geometry.dispose();o.material.dispose();}markers=[];line=null;measurePoints=[];}
  function fit(view=lastView){if(!current||!camera)return;needsRender=true;lastView=view==='fit'?lastView:view;const box=new THREE.Box3().setFromObject(current.group),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()),radius=Math.max(...size.toArray(),.01);controls.target.copy(center);const direction=lastView==='front'?new THREE.Vector3(0,0,1):lastView==='top'?new THREE.Vector3(0,1,.0001):lastView==='back'?new THREE.Vector3(-1,.55,-1.6).normalize():lastView==='side'?new THREE.Vector3(1,.4,-.2).normalize():new THREE.Vector3(1,.52,1.5).normalize(),distance=fittedDistance(box,direction,camera.fov,camera.aspect);camera.position.copy(center).addScaledVector(direction,distance);camera.near=radius/100;camera.far=radius*100;camera.updateProjectionMatrix();controls.minDistance=radius*.05;controls.maxDistance=radius*20;controls.update();resize();}
  function setModel(result,project,{refit=false}={}){if(!renderer)init();clearMeasure();current=result;const keyView=project.domain+':'+(project.params.exteriorMode??'')+':'+(project.params.representation??'');if(visualKey!==keyView){$('disciplineGrid').checked=false;visualKey=keyView;}if(result.environmentImage&&skyImage!==result.environmentImage){skyEnvironment?.dispose();skyEnvironment=reflectionEnvironment(renderer,result.environmentImage);skyImage=result.environmentImage;}scene.environment=result.environmentImage?skyEnvironment.texture:environment.texture;scene.environmentIntensity=project.domain==='exterior'?(result.environmentImage?.85:.35):.85;scene.add(result.group);if(grid){grid.removeFromParent();grid.geometry.dispose();grid.material.dispose();}if(ground){ground.removeFromParent();ground.geometry.dispose();ground.material.dispose();}const size=Math.max(...result.size,.01);grid=new THREE.GridHelper(size*3,24,0x9baaba,0xdce3eb);grid.position.y=-size*.008;grid.visible=$('disciplineGrid').checked;scene.add(grid);ground=new THREE.Mesh(new THREE.PlaneGeometry(size*100,size*100),new THREE.MeshStandardMaterial({color:0xe8eae8,roughness:1}));ground.rotation.x=-Math.PI/2;ground.position.y=-size*.003;ground.receiveShadow=true;scene.add(ground);const key=scene.children.find(c=>c.isDirectionalLight&&c.castShadow);key.intensity=project.proposal?1.25:1.8;scene.children.find(c=>c.isHemisphereLight).intensity=project.proposal?.45:.7;key.position.set(-size*1.6,size*2.5,size*2);Object.assign(key.shadow.camera,{left:-size*1.2,right:size*1.2,top:size*1.2,bottom:-size*1.2,near:.001,far:size*12});key.shadow.camera.updateProjectionMatrix();key.shadow.normalBias=size*.0001;key.shadow.bias=-.0001;
    $('disciplineTitle').textContent=project.domain==='exterior'?(project.proposal?'Un edificio, en profundidad.':'Del alzado al volumen.'):project.domain==='structure'?'Ejes que toman forma.':'Del perfil a la pieza.';$('disciplineAssumptions').textContent=result.assumptions.join(' ');$('disciplineDesignStatus').textContent=project.proposal?'Propuesta 3D · huecos y marcos con profundidad · laterales y fondo diseñados':project.section?'Corte longitudinal abierto · '+project.section.profiles.length+' regiones materiales · '+project.section.balls.length+' detalles circulares observados':project.hasDesign?'Acabados del Paso 2 · '+(project.designKind==='generated'?'Diseño generado con IA':'Presentación del proyecto')+' · revestimiento y vidrios vinculados':'Geometría del dibujo · revisa sus dimensiones antes de continuar';$('disciplineBadge').textContent=(project.calibration?(project.calibration.source==='cad-units'?'Unidades CAD declaradas':'Escala XY calibrada'):'Escala provisional')+' · Parámetros por revisar';$('disciplineSummary').textContent=`${result.parts} ${project.domain==='structure'?'barras':project.proposal?'componentes':'cuerpos'} · ${result.size.map(n=>(n*1000).toLocaleString('es-CL',{maximumFractionDigits:1})).join(' × ')} mm · ${project.domain==='mechanical'&&project.params.operation==='revolve'?(project.section?'Corte longitudinal · material y vacíos observados':'Envolvente de revolución'):project.domain==='structure'?'Modelo de ejes y secciones':project.proposal?'Propuesta arquitectónica tridimensional':'Extrusión de perfiles'}`;applyDisplay();if(refit||!controls.target.lengthSq())fit();else resize();}
  function applyDisplay(){needsRender=true;if(!current)return;const box=new THREE.Box3().setFromObject(current.group),center=box.getCenter(new THREE.Vector3()),cut=$('disciplineCut').checked?new THREE.Plane(new THREE.Vector3(0,0,-1),center.z):null;current.group.traverse(o=>{if(!o.isMesh)return;for(const m of Array.isArray(o.material)?o.material:[o.material]){m.wireframe=$('disciplineWire').checked;m.clippingPlanes=cut?[cut]:[];m.clipShadows=true;m.needsUpdate=true;}});if(grid)grid.visible=$('disciplineGrid').checked;}
  function pick(event){needsRender=true;if(!measure||!current||event.button!==0)return;const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((event.clientX-r.left)/r.width*2-1,-(event.clientY-r.top)/r.height*2+1),camera);const hits=ray.intersectObject(current.group,true).filter(h=>!h.object.userData.annotation&&(!$('disciplineCut').checked||h.point.z<=new THREE.Box3().setFromObject(current.group).getCenter(new THREE.Vector3()).z));if(!hits.length)return;if(measurePoints.length===2)clearMeasure();const point=hits[0].point;measurePoints.push(point.clone());const radius=Math.max(...current.size)*.008,marker=new THREE.Mesh(new THREE.SphereGeometry(radius,12,8),new THREE.MeshBasicMaterial({color:0xe18b35,depthTest:false}));marker.position.copy(point);marker.renderOrder=100;scene.add(marker);markers.push(marker);if(measurePoints.length===2){line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(measurePoints),new THREE.LineBasicMaterial({color:0x0073bf,depthTest:false}));scene.add(line);$('disciplineDistance').textContent=`${(measurePoints[0].distanceTo(measurePoints[1])*1000).toLocaleString('es-CL',{maximumFractionDigits:2})} mm · Distancia entre superficies del modelo${current.assumptions.some(a=>a.startsWith('Escala provisional'))?' · Provisional':''}`;}else $('disciplineDistance').textContent='Primer punto sobre superficie · marca el segundo';}
  for(const button of host.querySelectorAll('[data-view]'))button.onclick=()=>fit(button.dataset.view);for(const id of ['disciplineWire','disciplineCut','disciplineGrid'])$(id).onchange=applyDisplay;
  $('disciplineMeasure').onclick=()=>{measure=!measure;clearMeasure();if(controls)controls.enabled=!measure;$('disciplineMeasure').setAttribute('aria-pressed',String(measure));$('disciplineDistance').textContent=measure?'Marca dos puntos sobre las superficies 3D':'Órbita libre · rueda para acercar';};
  $('disciplineCapture').onclick=()=>{if(!renderer||!current)return;renderer.render(scene,camera);renderer.domElement.toBlob(b=>b&&download(b,'prodalam-estudio-3d.png'));};$('disciplineJSON').onclick=()=>onExport?.();$('disciplineSTL').onclick=()=>{if(current)download(new Blob([modelSTL(current.group)],{type:'model/stl'}),'prodalam-modelo-unidades-mm.stl');};
  return {setModel,show(value){visible=value;if(value){init();resize();needsRender=true;renderer.setAnimationLoop(()=>{const changed=controls.update();if(changed||needsRender){renderer.render(scene,camera);needsRender=false;}});}else renderer?.setAnimationLoop(null);},clear(){clearMeasure();current=null;visualKey=null;measure=false;if(controls)controls.enabled=true;$('disciplineMeasure').setAttribute('aria-pressed','false');$('disciplineWire').checked=false;$('disciplineCut').checked=false;$('disciplineGrid').checked=true;$('disciplineDistance').textContent='Órbita libre · rueda para acercar';},dispose(){renderer?.setAnimationLoop(null);controls?.dispose();skyEnvironment?.dispose();environment?.dispose();renderer?.dispose();grid?.geometry.dispose();grid?.material.dispose();ground?.geometry.dispose();ground?.material.dispose();clearMeasure();},get camera(){return camera;}};
}
